function bind(){app.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{view=b.dataset.nav;render();window.scrollTo(0,0);});app.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{try{await actions[b.dataset.action]();}catch(e){toast(e.message);}});app.querySelector('#period')?.addEventListener('change',e=>{periodName=e.target.value;render();});app.querySelectorAll('[data-edit-account]').forEach(b=>b.onclick=()=>accountForm(b.dataset.editAccount));app.querySelectorAll('[data-edit-asset]').forEach(b=>b.onclick=()=>assetForm(b.dataset.editAsset));app.querySelectorAll('[data-edit-debt]').forEach(b=>b.onclick=()=>debtForm(b.dataset.editDebt));app.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>eventDetail(b.dataset.event));app.querySelectorAll('[data-op]').forEach(b=>b.onclick=()=>operationForm(b.dataset.op,{asset:b.dataset.asset,debt:b.dataset.debt}));app.querySelectorAll('[data-debt-tab]').forEach(b=>b.onclick=()=>{debtTab=b.dataset.debtTab;render();});app.querySelectorAll('[data-rate]').forEach(b=>b.onclick=()=>rateForm(b.dataset.rate));app.querySelectorAll('[data-entity-history]').forEach(b=>b.onclick=()=>{const ev=E.sorted(state).filter(e=>e.postings.some(p=>p.id===b.dataset.entityHistory));show('История записи',eventTable([...ev].reverse()));modal.querySelectorAll('[data-event]').forEach(btn=>btn.onclick=()=>eventDetail(btn.dataset.event));});app.querySelectorAll('[data-archive]').forEach(b=>b.onclick=()=>{const [key,id]=b.dataset.archive.split(':'),item=state[key].find(x=>x.id===id);confirmation(item.archived?'Восстановить запись?':'Архивировать запись?',`История и текущий вклад в капитал сохранятся. ${item.archived?'Запись снова будет доступна для операций.':'Архивная запись будет недоступна для новых операций.'}`,async()=>{const n=structuredClone(state);n[key].find(x=>x.id===id).archived=!item.archived;await persist(n);});});app.querySelectorAll('[data-delete-entity]').forEach(b=>b.onclick=()=>{const [key,id]=b.dataset.deleteEntity.split(':');confirmation('Удалить пустой счёт?','Счёт без остатка и связанных операций будет удалён.',async()=>{const n=structuredClone(state);if(n.events.some(e=>e.postings.some(p=>p.id===id)))throw Error('У счёта есть история');n[key]=n[key].filter(x=>x.id!==id);await persist(n);});});app.querySelector('#search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;filters.q=e.target.value;render();const q=app.querySelector('#search');q.focus();q.setSelectionRange(pos,pos);});for(const k of ['kind','account','status','from','to'])app.querySelector('#filter-'+k)?.addEventListener('change',e=>{filters[k]=e.target.value;render();});}
new BroadcastChannel('my-capital-changes').onmessage=e=>{if(state&&e.data!==state.revision){stale=true;if(!modal.open)render();else toast('Данные изменены в другой вкладке. Перед сохранением обновите страницу.');}};
try{state=await DB.open();render();}catch(e){app.innerHTML=`<main class="onboard"><h1>Не удалось открыть данные</h1><p class="error">${esc(e.message)}</p><p>Существующая база не перезаписана. Не очищайте данные браузера. Проверьте доступность IndexedDB и откройте приложение в обычном окне браузера.</p><button id="reload">Повторить</button><button id="recover">Скачать сохранённое состояние</button></main>`;document.querySelector('#reload').onclick=()=>location.reload();document.querySelector('#recover').onclick=async()=>{try{const req=indexedDB.open('my-capital-local');req.onsuccess=()=>{const q=req.result.transaction('state').objectStore('state').get('main');q.onsuccess=()=>download(JSON.stringify(q.result,null,2),'Мой-капитал-восстановление.json','application/json');};req.onerror=()=>toast('Не удалось прочитать локальную базу');}catch(err){toast(err.message)}};}
